// Immortals and their clerics, from the Codex Immortalis (Marco Dalmonte), "Classic D&D Stats" of each entry.
// Extra spells per Immortal: Tome of the Magic of Mystara Vol. 2 (Divine Magic), Appendix "Additional spells of each Immortal".
//   extraSpells: { id (spells_db), level (as granted to this Immortal's clerics), replaces? (the common spell it takes the place of) }
//   druidSpellLevels: the clerics also pray for every druid spell up to this level.

export interface DeitySpell { id: string; level: number; replaces?: string; }
export interface DeityData {
    weapons: string;            // favoured weapon(s), comma list (empty when "None")
    allowedWeapons: string;     // weapons named as also allowed, comma list
    weaponsText: string;        // the Codex wording
    description: string;
    titles: string;
    rank: string;
    alignment: string;
    sphere: string;
    symbol: string;
    portfolio: string;
    followers: string;
    clericPowers: string;
    paladinPowers: string;
    avengerPowers: string;
    codexSpells: string;
    source: string;
    extraSpells: DeitySpell[];
    spellNote: string;
    druidSpellLevels?: number;
    noClerics?: string;         // why this Immortal is not offered to divine casters
}

