    "Bagni Gullymaw": {"weapons": "", "allowedWeapons": "", "weaponsText": "Natural weapons (allowed only two-handed weapons)", "description": "13th (Celestial), CE, Sphere of Entropy. Violence, cannibalism, trolls, humanoids", "titles": "(The Great Devourer, Yemekershey) Patron of Trolls, Patron of Cannibalism", "rank": "13th (Celestial)", "alignment": "CE", "sphere": "Entropy", "symbol": "Two blood dripping fangs", "portfolio": "Violence, cannibalism, trolls, humanoids", "followers": "Clerics and followers must be Chaotic", "clericPowers": "Each day clerics can recover one spell they cast within the last 10 hours if they devour a creature with the same HD as the power level of the spell (the ritual takes 1 turn per HD of the victim)", "paladinPowers": "", "avengerPowers": "", "codexSpells": "feign death (2nd), demonic metamorphosis (7th)", "source": "HW, GAZ10, WotI", "extraSpells": [{"id": "imm_claws_of_the_demon", "level": 1}, {"id": "imm_bleeding_wound", "level": 1, "replaces": "Fascinate animals"}, {"id": "imm_resistance", "level": 1}, {"id": "imm_boiling_blood", "level": 2}, {"id": "imm_devastating_touch", "level": 2}, {"id": "imm_enlarge", "level": 3}, {"id": "imm_entropic_sphere", "level": 3}, {"id": "imm_insatiable_hunger", "level": 4, "replaces": "Freedom of movement"}, {"id": "imm_sacrilegious_influence", "level": 4}, {"id": "imm_entropic_arrows", "level": 5}, {"id": "imm_empathic_suffering", "level": 5}, {"id": "imm_entropic_shield", "level": 6}, {"id": "imm_symbol_of_pain", "level": 6}, {"id": "imm_demonshape", "level": 7}, {"id": "imm_acid_rain", "level": 7}], "spellNote": ""},
