    "Bastet": {"weapons": "warclaws", "allowedWeapons": "dagger, javelin, spear", "weaponsText": "Natural claws and warclaws (allowed all types of dagger, javelin, spear and natural weapons)", "description": "15th (Celestial), CN, Sphere of Thought. Rakasta, felines, luck, instincts, life, fertility, prosperity", "titles": "Patroness of Rakasta and Cats, Patroness of Instincts and Luck, The Lost Mother", "rank": "15th (Celestial)", "alignment": "CN", "sphere": "Thought", "symbol": "Silhouette of a black cat", "portfolio": "Rakasta, felines, luck, instincts, life, fertility, prosperity", "followers": "Any; Clerics must be Neutral or Chaotic", "clericPowers": "+1 bonus to Dexterity, bonus Alertness general skill", "paladinPowers": "", "avengerPowers": "", "codexSpells": "", "source": "Dragon #247", "extraSpells": [{"id": "imm_feather_fall", "level": 1}, {"id": "imm_silence", "level": 2}, {"id": "imm_fertility", "level": 3}, {"id": "imm_minor_luck", "level": 3, "replaces": "Spell of Striking*"}, {"id": "imm_sixth_sense", "level": 4}, {"id": "imm_cat_s_grace", "level": 5}, {"id": "imm_mislead", "level": 6}, {"id": "imm_aura_of_unpredictability", "level": 7, "replaces": "Rise of heroes"}, {"id": "arcane_create_normal_monsters", "level": 7}], "spellNote": ""},
