    "Kagyar the Artisan": {"weapons": "Warhammer", "allowedWeapons": "throwing hammer mace, dagger, battle axe, poleaxe", "weaponsText": "Warhammer (also allowed throwing hammer mace, dagger, battle axe and poleaxe)", "description": "28th (Eternal), N, Sphere of Matter. Dwarves, crafts, metallurgy, sculpture, knowledge, miners", "titles": "(Belsamas, Ka—Gar, Modsognir, Nin—Agar, Flasheyes, Pater, Ptahr) Patron of Dwarves, Patron of Craftsmen, Protector of Miners", "rank": "28th (Eternal)", "alignment": "N", "sphere": "Matter", "symbol": "Hammer and chisel crossed", "portfolio": "Dwarves, crafts, metallurgy, sculpture, knowledge, miners", "followers": "Any; clerics must be Lawful or Neutral", "clericPowers": "+1 bonus to Constitution, +1 bonus to ST vs. Spells; at 9th level this power is replaced by the Mystic ability resistance; +2 bonus to one type of craft skill (not free). No cleric of Kagyar can turn undead. Any cleric of Kagyar (exclusively dwarves) belongs to the caste of the Keepers of the Forge of Power (see the Tome of the Magic of Mystara for further details)", "paladinPowers": "", "avengerPowers": "", "codexSpells": "", "source": "GAZ6, HW, HWR2, WotI, DotE, SCS", "extraSpells": [{"id": "imm_ceremony", "level": 1, "replaces": "Sacred aura"}, {"id": "imm_dig", "level": 1}, {"id": "imm_stone_hands", "level": 2}, {"id": "imm_meld_into_stone", "level": 3, "replaces": "Continual light*"}, {"id": "imm_fist_of_rock", "level": 3}, {"id": "imm_stone_shape", "level": 4}, {"id": "imm_mighty_blow", "level": 5, "replaces": "Create normal animals"}, {"id": "imm_fabricate", "level": 5}, {"id": "arcane_stoneform", "level": 6}, {"id": "arcane_ironform", "level": 7}], "spellNote": ""},
    "Kallala of the Seven Veils": {"weapons": "", "allowedWeapons": "knife/dagger, spear", "weaponsText": "None (allowed all kinds of knife/dagger and spear)", "description": "14th (Celestial), CN, Sphere of Time. Nixies, seduction, malice, cleverness, femininity (cid:3) 9", "titles": "(Ran) Patroness of Nixies, Patroness of Seduction and Malice", "rank": "14th (Celestial)", "alignment": "CN", "sphere": "Time", "symbol": "Seven veils with the colours of the rainbow forming a circle", "portfolio": "Nixies, seduction, malice, cleverness, femininity (cid:3) 9", "followers": "Any; clerics must be Neutral or Chaotic", "clericPowers": "+2 bonus to Charisma, +2 bonus to any one skill among the following: Seduction, Persuasion, Deceit", "paladinPowers": "", "avengerPowers": "", "codexSpells": "", "source": "PC3, WotI", "extraSpells": [{"id": "arcane_charm_person", "level": 1}, {"id": "imm_ecstasy", "level": 2}, {"id": "imm_marine_vortex", "level": 2, "replaces": "Sure step"}, {"id": "imm_summon_whirlwind", "level": 3, "replaces": "Gentle repose"}, {"id": "imm_fascination", "level": 3, "replaces": "Continual light*"}, {"id": "imm_liquid_form", "level": 3}, {"id": "imm_seaweed_to_snakes", "level": 4, "replaces": "Freedom of movement"}, {"id": "arcane_charm_monster", "level": 4}, {"id": "imm_mind_fog", "level": 5}, {"id": "imm_mass_suggestion", "level": 6}, {"id": "imm_marine_fury", "level": 7, "replaces": "Earthquake"}, {"id": "imm_dimensional_refuge", "level": 7}], "spellNote": ""},
    "Karaash": {"weapons": "Two handed sword", "allowedWeapons": "crossbows", "weaponsText": "Two handed sword (allowed all bludgeoning weapons and crossbows)", "description": "6th (Initiate), N, Sphere of Thought. Humanoids, battle, tactics, conquest, rule of the strongest", "titles": "(Ilneval, Hong-Tzu) Patron of Battle and Conquest", "rank": "6th (Initiate)", "alignment": "N", "sphere": "Thought", "symbol": "A huge two handed greatsword with wicked looking edges on its upper part", "portfolio": "Humanoids, battle, tactics, conquest, rule of the strongest", "followers": "Any", "clericPowers": "Bonus general skills Leadership and Terrorise; if cleric uses a BLESSED two handed greatsword the damage he causes can be healed only magically", "paladinPowers": "", "avengerPowers": "+1 bonus to hit and damage rolls vs. infidels (anybody not worshipping Karaash)", "codexSpells": "", "source": "GAZ10, HW, WotI, SCS, OHP", "extraSpells": [{"id": "arcane_magic_missile", "level": 1}, {"id": "imm_offensive_impulse", "level": 1, "replaces": "Fascinate animals"}, {"id": "imm_sure_strike", "level": 2}, {"id": "imm_enlarge", "level": 3}, {"id": "imm_blood_thirst", "level": 3, "replaces": "Glyph of interdiction"}, {"id": "imm_extended_range", "level": 4}, {"id": "imm_war_cry", "level": 4, "replaces": "Programmed cure"}, {"id": "imm_siege_fire", "level": 5}, {"id": "imm_deadly_weapon", "level": 6}, {"id": "imm_enchanted_standard", "level": 6, "replaces": "Animate objects"}, {"id": "imm_heroism", "level": 7}, {"id": "imm_victory", "level": 7, "replaces": "Luck"}], "spellNote": ""},
