    "Lornasen": {"weapons": "", "allowedWeapons": "", "weaponsText": "None (allowed all bludgeoning weapons)", "description": "8th (Temporal), NG, Sphere of Energy. Beauty, perfection, grace, spring, plants, nature, fertility, elves", "titles": "Patroness of Eternal Beauty and Grace, Queen of the Spring, Keeper of Lothbarth", "rank": "8th (Temporal)", "alignment": "NG", "sphere": "Energy", "symbol": "A hawthorn in bloom", "portfolio": "Beauty, perfection, grace, spring, plants, nature, fertility, elves", "followers": "Any; clerics must be Neutral", "clericPowers": "+1 bonus to Charisma, power of speaking with plants for 1 turn per day. Clerics of Lornasen have access to 1st level druid spells as well all cleric spells", "paladinPowers": "", "avengerPowers": "", "codexSpells": "", "source": "IM2", "extraSpells": [], "spellNote": "All the clerics of Lornasen are sylvan druids and use that Class’s spell list."},
