    "Maat": {"weapons": "Khopesh, bastard sword, katana", "allowedWeapons": "", "weaponsText": "Khopesh and bastard sword or katana (allowed all bludgeoning weapons)", "description": "30th (Eternal), LG, Sphere of Matter. Justice, honour, virtue, honesty, order, integrity, loyalty, redemption, fighting evil and chaos", "titles": "(Mitra, Snotra) Patroness of Honour and Justice, Patroness of Honesty and Purity", "rank": "30th (Eternal)", "alignment": "LG", "sphere": "Matter", "symbol": "A white plume", "portfolio": "Justice, honour, virtue, honesty, order, integrity, loyalty, redemption, fighting evil and chaos", "followers": "Lawful or Neutral; clerics must be Lawful", "clericPowers": "+1 bonus to Strength and Wisdom, bonus \"Detect Lies\" skill. Cleric are obliged to respect Maat's Code (the most important points of this Lawful code are: always issue a challenge before attacking; give a swift and honourable death to a fellow brother if he demands it; never reveal the order's secrets nor betray the cult; always fight injustice respecting the laws; offer sacrifices at the end of each successful battle)", "paladinPowers": "Lay on hands, bonus \"Detect lies\" skill, obliged to follow Maat's code (see above)", "avengerPowers": "", "codexSpells": "", "source": "Master & Immortal set, WotI", "extraSpells": [{"id": "imm_friendship", "level": 1}, {"id": "imm_zone_of_truth", "level": 2}, {"id": "imm_destroy_undead", "level": 3}, {"id": "imm_honesty", "level": 3, "replaces": "Glyph of interdiction"}, {"id": "imm_spirit_armour", "level": 4}, {"id": "imm_scourge_of_evil", "level": 4}, {"id": "imm_purity_of_spirit", "level": 4, "replaces": "Damage resistance"}, {"id": "imm_telepathy", "level": 5}, {"id": "imm_flame_of_justice", "level": 6}, {"id": "imm_purifying_energy", "level": 7}, {"id": "imm_interdiction_of_the_tomb", "level": 7, "replaces": "Earthquake"}], "spellNote": ""},
