    "Madarua": {"weapons": "Short sword", "allowedWeapons": "short spear, sickle", "weaponsText": "Short sword (allowed short spear, sickle, and all one-handed bludgeoning weapons)", "description": "19th (Empyreal), NG, Sphere of Energy. Amazons and fighting women, courage, life cycle, fertility, Cynidicea and Kerswig", "titles": "(Sif, Yarella) Patroness of Warrior Maidens and Amazons, Patroness of Cynidicea and Kerswig, Patroness of Fertility", "rank": "19th (Empyreal)", "alignment": "NG", "sphere": "Energy", "symbol": "A sickle and a short sword crossed under a woman’s visage", "portfolio": "Amazons and fighting women, courage, life cycle, fertility, Cynidicea and Kerswig", "followers": "Any; clerics must be Lawful o Neutral", "clericPowers": "+1 bonus to Strength, free Fighting Instinct general skill, +2 to any one skill tied to agriculture or nature (not free). Madarua accepts only female clerics", "paladinPowers": "", "avengerPowers": "", "codexSpells": "", "source": "B4, WotI, Dungeon magazine #53 (Yarella)", "extraSpells": [{"id": "imm_spear_of_thorns", "level": 1}, {"id": "imm_sure_strike", "level": 2}, {"id": "imm_bravery", "level": 3, "replaces": "Continual light*"}, {"id": "imm_fertility", "level": 3}, {"id": "imm_plant_growth", "level": 4}, {"id": "imm_scourge_of_evil", "level": 4}, {"id": "imm_bull_s_strength", "level": 5}, {"id": "imm_deadly_weapon", "level": 6}, {"id": "imm_heroism", "level": 7}], "spellNote": ""},
    "Mahmatti Running Elk": {"weapons": "", "allowedWeapons": "", "weaponsText": "None (allowed all bludgeoning weapons)", "description": "13th (Celestial), N, Sphere of Energy. Clan of the elk, protecting the children of Atruaghin, wisdom, nature, magic", "titles": "Patron of the Clan of the Elk", "rank": "13th (Celestial)", "alignment": "N", "sphere": "Energy", "symbol": "A clay pipe", "portfolio": "Clan of the elk, protecting the children of Atruaghin, wisdom, nature, magic", "followers": "Lawful or Neutral; clerics must be Neutral", "clericPowers": "+1 bonus to Wisdom. Clerics of Mahmatti have access to the first three levels of druid spells as well as those of the cleric, but have the same limitations as druids for using weapons, armour and magic items. Domains: Energy, Magic, Plant, Animal", "paladinPowers": "", "avengerPowers": "", "codexSpells": "", "source": "GAZ14, WotI", "extraSpells": [{"id": "imm_detect_totem", "level": 1, "replaces": "Spear of thorns"}, {"id": "imm_locate_totem", "level": 2, "replaces": "Gust of wind"}, {"id": "imm_summon_totem", "level": 3, "replaces": "Snow storm"}, {"id": "imm_thunder_drum", "level": 4, "replaces": "Earthmaw"}, {"id": "imm_fire_gate", "level": 5, "replaces": "Power of the rainbow"}, {"id": "imm_control_totem", "level": 6, "replaces": "Ravaging creepers"}, {"id": "arcane_polymorph_other", "level": 7, "replaces": "Earthquake"}], "spellNote": "The clerics of Mahmatti are all druids and use that Class’s spell list. The spells listed below replace the druid spell between the parentheses."},
    "Malafor": {"weapons": "", "allowedWeapons": "trident, short spear, dagger, net", "weaponsText": "None (allowed the trident, the short spear, the dagger and the net)", "description": "13th (Celestial), NG, Sphere of Matter. Merrow, dolphins, protection and prosperity of the aquatic races and the oceanic ecosystem.", "titles": "Patron of Merrow, Dolphins' Friend", "rank": "13th (Celestial)", "alignment": "NG", "sphere": "Matter", "symbol": "A blue dolphin", "portfolio": "Merrow, dolphins, protection and prosperity of the aquatic races and the oceanic ecosystem.", "followers": "Any; the clerics must be Neutral or Lawful", "clericPowers": "The clerics can magically turn into a dolphin once a day (acquires physical statistics of the dolphin, maintains his own mental characteristics, Saving Throws and THAC0, but cannot carry with him objects nor use his own special powers, can speak Dolphin tongue, +2 bonus to Train Dolphins general skill (not free)", "paladinPowers": "", "avengerPowers": "", "codexSpells": "", "source": "PC3, WotI", "extraSpells": [{"id": "imm_locate_species", "level": 1}, {"id": "imm_flaming_liquid", "level": 2, "replaces": "Find traps"}, {"id": "imm_swim", "level": 2}, {"id": "imm_marine_vortex", "level": 2, "replaces": "Sure step"}, {"id": "imm_summon_whirlwind", "level": 3, "replaces": "Gentle repose"}, {"id": "imm_animal_form", "level": 3}, {"id": "imm_seaweed_to_snakes", "level": 4, "replaces": "Freedom of movement"}, {"id": "imm_anti_animal_barrier", "level": 4}, {"id": "imm_scourge_of_evil", "level": 4}, {"id": "imm_commune_with_nature", "level": 5}, {"id": "imm_control_currents", "level": 6}, {"id": "imm_marine_fury", "level": 7, "replaces": "Earthquake"}, {"id": "arcane_polymorph_other", "level": 7}], "spellNote": ""},
