    "Nob Nar": {"weapons": "Short sword", "allowedWeapons": "short spear", "weaponsText": "Short sword (allowed all bludgeoning weapon and the short spear)", "description": "5th (Initiate), NG, Sphere of Thought. Halflings, wanderers and adventurers, audacity, heroic deeds, revelry", "titles": "Patron of Halflings, Protector of the Five Shires, Patron of Adventurers and Audacity", "rank": "5th (Initiate)", "alignment": "NG", "sphere": "Thought", "symbol": "A downwards pointing sword curved to form a fang", "portfolio": "Halflings, wanderers and adventurers, audacity, heroic deeds, revelry", "followers": "Followers and clerics can be of any alignment", "clericPowers": "+1 bonus to Dexterity, +2 bonus to one ability chosen from resistance, run, taunt, alertness and courage (not free)", "paladinPowers": "Paladins of Nob Nar are the Hin Masters (see the rules relating to the class in GAZ8 and in the Tome of the Magic of Mystara)", "avengerPowers": "", "codexSpells": "", "source": "GAZ8", "extraSpells": [{"id": "imm_ceremony", "level": 1, "replaces": "Sacred aura"}, {"id": "imm_poetic_inspiration", "level": 2, "replaces": "Bless*"}, {"id": "imm_bravery", "level": 3, "replaces": "Continual light*"}, {"id": "imm_scourge_of_evil", "level": 4}], "spellNote": "The clerics of Nob Nar are all Hero Bards with access to these replacement spells. In the Five Shires the paladins of Nob Nar and of the other High Heroes are the Hin Masters (who have their own spell list)."},
