    "Ordana": {"weapons": "Club, quarterstaff", "allowedWeapons": "", "weaponsText": "Club or quarterstaff (allowed all bludgeoning weapons)", "description": "31st (Hierarch), NG, Sphere of Time. Nature, fertility, protection of forests and woodland beings (especially elves and treants)", "titles": "(Mother Forest, Thendara, Breig, Tawnia, Uì) Patroness of Sylvan Races, Mother of the Elves", "rank": "31st (Hierarch)", "alignment": "NG", "sphere": "Time", "symbol": "An oak leaf", "portfolio": "Nature, fertility, protection of forests and woodland beings (especially elves and treants)", "followers": "Any; clerics must be Neutral", "clericPowers": "Clerics gain thieves' skills hide in shadows and move silently as thief or same level only in woodland areas; free Nature Lore and Survival (Forest) general skills; +2 bonus to Herbalism skill", "paladinPowers": "", "avengerPowers": "", "codexSpells": "", "source": "GAZ5, GAZ9, HW, WotI, SCS", "extraSpells": [], "spellNote": "All the clerics of Ordana are sylvan druids and use the Druid Class’s spell list."},
