    "Razud": {"weapons": "Mace", "allowedWeapons": "", "weaponsText": "Mace (allowed all bludgeoning weapons)", "description": "31st (Hierarch), NG, Sphere of Energy (cid:2)(cid:2) 11. Alphatians, self-determination, independence, courage, freedom, authority, strong willed characters", "titles": "Patron of Self-determination and Independence, Patron of the Alphatians", "rank": "31st (Hierarch)", "alignment": "NG", "sphere": "Energy (cid:2)(cid:2) 11", "symbol": "The granite tree (a tree of any kind, made of stone)", "portfolio": "Alphatians, self-determination, independence, courage, freedom, authority, strong willed characters", "followers": "Any", "clericPowers": "+1 bonus to Wisdom and Initiative rolls, +2 bonus to Saving Throws vs. spells of domination or charm", "paladinPowers": "", "avengerPowers": "", "codexSpells": "", "source": "HW, DotE, WotI", "extraSpells": [{"id": "imm_resistance", "level": 1}, {"id": "imm_mind_shield", "level": 2}, {"id": "imm_bravery", "level": 3, "replaces": "Continual light*"}, {"id": "imm_concentration", "level": 3}, {"id": "arcane_polymorph_self", "level": 4}, {"id": "imm_scourge_of_evil", "level": 4}, {"id": "imm_mighty_blow", "level": 5, "replaces": "Create normal animals"}, {"id": "imm_bull_s_strength", "level": 5}, {"id": "imm_forceful_hand", "level": 6}, {"id": "imm_steelskin", "level": 7}], "spellNote": ""},
